"""Consistent JSON error handling.

All errors are rendered as:
    {"error": {"code": "<machine_code>", "message": "<human message>", "details": {...}}}
"""
from flask import jsonify
from werkzeug.exceptions import HTTPException


class ApiError(Exception):
    """Application-level error carrying an HTTP status and machine-readable code."""

    status_code = 400
    code = "bad_request"

    def __init__(self, message: str, *, status_code: int | None = None,
                 code: str | None = None, details: dict | None = None):
        super().__init__(message)
        self.message = message
        if status_code is not None:
            self.status_code = status_code
        if code is not None:
            self.code = code
        self.details = details or {}


class ValidationApiError(ApiError):
    status_code = 422
    code = "validation_error"


class AuthError(ApiError):
    status_code = 401
    code = "unauthorized"


class ForbiddenError(ApiError):
    status_code = 403
    code = "forbidden"


class NotFoundError(ApiError):
    status_code = 404
    code = "not_found"


class ConflictError(ApiError):
    status_code = 409
    code = "conflict"


class RateLimitError(ApiError):
    status_code = 429
    code = "rate_limit_exceeded"

    def __init__(self, message: str = "Rate limit exceeded", *, retry_after: int = 0,
                 details: dict | None = None):
        super().__init__(message, details=details)
        self.retry_after = retry_after


def error_response(status_code: int, code: str, message: str, details: dict | None = None):
    payload = {"error": {"code": code, "message": message, "details": details or {}}}
    response = jsonify(payload)
    response.status_code = status_code
    return response


HTTP_CODE_NAMES = {
    400: "bad_request",
    401: "unauthorized",
    403: "forbidden",
    404: "not_found",
    405: "method_not_allowed",
    409: "conflict",
    415: "unsupported_media_type",
    422: "validation_error",
    429: "rate_limit_exceeded",
    500: "internal_server_error",
}


def register_error_handlers(app):
    @app.errorhandler(ApiError)
    def handle_api_error(err: ApiError):
        response = error_response(err.status_code, err.code, err.message, err.details)
        if isinstance(err, RateLimitError) and err.retry_after:
            response.headers["Retry-After"] = str(err.retry_after)
        return response

    @app.errorhandler(HTTPException)
    def handle_http_exception(err: HTTPException):
        code = HTTP_CODE_NAMES.get(err.code, "error")
        return error_response(err.code or 500, code, err.description or err.name)

    @app.errorhandler(Exception)
    def handle_unexpected(err: Exception):
        app.logger.exception("Unhandled exception")
        if app.config.get("TESTING") and app.config.get("RAISE_UNHANDLED"):
            raise err
        return error_response(500, "internal_server_error",
                              "An unexpected error occurred.")

"""Lightweight declarative input validation.

A schema is a dict mapping field name -> Field. `validate(schema, data)` returns
the cleaned data or raises ValidationApiError with per-field details, e.g.:

    {"error": {"code": "validation_error", ...,
               "details": {"fields": {"email": "Not a valid email address."}}}}
"""
import re

from flask import request

from .errors import ValidationApiError

EMAIL_RE = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")

_MISSING = object()


class Field:
    type = None
    type_error = "Invalid type."

    def __init__(self, *, required=True, default=_MISSING, min_length=None,
                 max_length=None, min_value=None, max_value=None, choices=None,
                 strip=True):
        self.required = required
        self.default = default
        self.min_length = min_length
        self.max_length = max_length
        self.min_value = min_value
        self.max_value = max_value
        self.choices = choices
        self.strip = strip

    def clean(self, value):
        """Return cleaned value or raise ValueError(message)."""
        value = self.coerce(value)
        if isinstance(value, str) and self.strip:
            value = value.strip()
        if self.min_length is not None and len(value) < self.min_length:
            raise ValueError(f"Must be at least {self.min_length} characters long.")
        if self.max_length is not None and len(value) > self.max_length:
            raise ValueError(f"Must be at most {self.max_length} characters long.")
        if self.min_value is not None and value < self.min_value:
            raise ValueError(f"Must be >= {self.min_value}.")
        if self.max_value is not None and value > self.max_value:
            raise ValueError(f"Must be <= {self.max_value}.")
        if self.choices is not None and value not in self.choices:
            raise ValueError(f"Must be one of: {', '.join(map(str, self.choices))}.")
        return value

    def coerce(self, value):
        if self.type is not None and not isinstance(value, self.type):
            raise ValueError(self.type_error)
        return value


class String(Field):
    type = str
    type_error = "Must be a string."


class Integer(Field):
    type_error = "Must be an integer."

    def coerce(self, value):
        # bool is a subclass of int; reject it explicitly.
        if isinstance(value, bool) or not isinstance(value, int):
            raise ValueError(self.type_error)
        return value


class Email(String):
    def clean(self, value):
        value = super().clean(value)
        if not EMAIL_RE.match(value):
            raise ValueError("Not a valid email address.")
        return value.lower()


def validate(schema: dict, data) -> dict:
    if not isinstance(data, dict):
        raise ValidationApiError("Request body must be a JSON object.")

    errors: dict[str, str] = {}
    cleaned: dict = {}

    for name, field in schema.items():
        if name not in data or data[name] is None:
            if field.required:
                errors[name] = "This field is required."
            elif field.default is not _MISSING:
                cleaned[name] = field.default
            continue
        try:
            cleaned[name] = field.clean(data[name])
        except ValueError as exc:
            errors[name] = str(exc)

    unknown = set(data) - set(schema)
    for name in unknown:
        errors[name] = "Unknown field."

    if errors:
        raise ValidationApiError("Input validation failed.",
                                 details={"fields": errors})
    return cleaned


def validate_json(schema: dict) -> dict:
    """Validate the current request's JSON body against a schema."""
    data = request.get_json(silent=True)
    if data is None:
        raise ValidationApiError("Request body must be valid JSON.")
    return validate(schema, data)

"""JWT creation/verification and route protection decorators."""
import uuid
from datetime import datetime, timezone
from functools import wraps

import jwt
from flask import current_app, g, request

from ..errors import AuthError, ForbiddenError
from ..models import User


def _make_token(user: User, token_type: str, ttl) -> str:
    now = datetime.now(timezone.utc)
    payload = {
        "sub": str(user.id),
        "role": user.role,
        "type": token_type,
        "iss": current_app.config["JWT_ISSUER"],
        "iat": now,
        "exp": now + ttl,
        "jti": uuid.uuid4().hex,
    }
    return jwt.encode(payload, current_app.config["SECRET_KEY"],
                      algorithm=current_app.config["JWT_ALGORITHM"])


def create_access_token(user: User) -> str:
    return _make_token(user, "access", current_app.config["JWT_ACCESS_TOKEN_TTL"])


def create_refresh_token(user: User) -> str:
    return _make_token(user, "refresh", current_app.config["JWT_REFRESH_TOKEN_TTL"])


def decode_token(token: str, expected_type: str = "access") -> dict:
    try:
        payload = jwt.decode(
            token,
            current_app.config["SECRET_KEY"],
            algorithms=[current_app.config["JWT_ALGORITHM"]],
            issuer=current_app.config["JWT_ISSUER"],
            options={"require": ["exp", "iat", "sub", "type"]},
        )
    except jwt.ExpiredSignatureError:
        raise AuthError("Token has expired.", code="token_expired")
    except jwt.InvalidTokenError:
        raise AuthError("Invalid token.", code="token_invalid")

    if payload.get("type") != expected_type:
        raise AuthError(f"Expected a {expected_type} token.", code="token_invalid")
    return payload


def _get_bearer_token() -> str:
    header = request.headers.get("Authorization", "")
    parts = header.split()
    if len(parts) != 2 or parts[0].lower() != "bearer":
        raise AuthError("Missing or malformed Authorization header.",
                        code="token_missing")
    return parts[1]


def _load_current_user(expected_type: str = "access") -> User:
    payload = decode_token(_get_bearer_token(), expected_type)
    user = User.query.get(int(payload["sub"]))
    if user is None:
        raise AuthError("User no longer exists.", code="token_invalid")
    return user


def auth_required(fn):
    """Require a valid access token; sets g.current_user."""

    @wraps(fn)
    def wrapper(*args, **kwargs):
        g.current_user = _load_current_user("access")
        return fn(*args, **kwargs)

    return wrapper


def admin_required(fn):
    """Require a valid access token belonging to an admin."""

    @wraps(fn)
    def wrapper(*args, **kwargs):
        user = _load_current_user("access")
        if user.role != "admin":
            raise ForbiddenError("Admin privileges required.")
        g.current_user = user
        return fn(*args, **kwargs)

    return wrapper

"""Pagination helpers for list endpoints."""
from flask import current_app, request, url_for

from .errors import ValidationApiError


def get_page_args() -> tuple[int, int]:
    """Read and validate ?page= and ?per_page= query params."""
    cfg = current_app.config
    errors = {}

    def read_int(name: str, default: int) -> int:
        raw = request.args.get(name)
        if raw is None:
            return default
        try:
            return int(raw)
        except ValueError:
            errors[name] = "Must be an integer."
            return default

    page = read_int("page", 1)
    per_page = read_int("per_page", cfg["PAGINATION_DEFAULT_PER_PAGE"])

    if not errors:
        if page < 1:
            errors["page"] = "Must be >= 1."
        if per_page < 1:
            errors["per_page"] = "Must be >= 1."
        elif per_page > cfg["PAGINATION_MAX_PER_PAGE"]:
            errors["per_page"] = f"Must be <= {cfg['PAGINATION_MAX_PER_PAGE']}."

    if errors:
        raise ValidationApiError("Invalid pagination parameters.",
                                 details={"fields": errors})
    return page, per_page


def paginate(query, serializer=lambda item: item.to_dict()) -> dict:
    """Paginate a SQLAlchemy query into a standard envelope."""
    page, per_page = get_page_args()
    total = query.order_by(None).count()
    pages = max(1, -(-total // per_page))  # ceil division, min 1
    items = query.limit(per_page).offset((page - 1) * per_page).all()

    def page_url(p):
        args = {**request.args, "page": p, "per_page": per_page}
        return url_for(request.endpoint, **args, **(request.view_args or {}))

    return {
        "data": [serializer(item) for item in items],
        "pagination": {
            "page": page,
            "per_page": per_page,
            "total": total,
            "pages": pages,
            "next": page_url(page + 1) if page < pages else None,
            "prev": page_url(page - 1) if page > 1 else None,
        },
    }

"""Authentication endpoints: register, login, refresh, whoami."""
from flask import Blueprint, g, jsonify

from ..audit import audit
from ..errors import AuthError, ConflictError
from ..extensions import db
from ..models import User
from ..rate_limit import rate_limit
from ..validation import Email, String, validate_json
from .jwt_utils import (auth_required, create_access_token,
                        create_refresh_token, decode_token, _get_bearer_token)

auth_bp = Blueprint("auth", __name__)

REGISTER_SCHEMA = {
    "email": Email(max_length=255),
    "password": String(min_length=8, max_length=128, strip=False),
}
LOGIN_SCHEMA = {
    "email": Email(max_length=255),
    "password": String(strip=False),
}


@auth_bp.post("/register")
@rate_limit("RATELIMIT_AUTH_LIMIT", "RATELIMIT_AUTH_WINDOW")
def register():
    data = validate_json(REGISTER_SCHEMA)
    if User.query.filter_by(email=data["email"]).first():
        raise ConflictError("A user with this email already exists.")

    user = User(email=data["email"])
    user.set_password(data["password"])
    db.session.add(user)
    db.session.flush()  # assign user.id
    audit("user.register", resource_type="user", resource_id=user.id,
          status_code=201, user_id=user.id)
    db.session.commit()
    return jsonify({"data": user.to_dict()}), 201


@auth_bp.post("/login")
@rate_limit("RATELIMIT_AUTH_LIMIT", "RATELIMIT_AUTH_WINDOW")
def login():
    data = validate_json(LOGIN_SCHEMA)
    user = User.query.filter_by(email=data["email"]).first()
    if user is None or not user.check_password(data["password"]):
        audit("auth.login_failed", detail=f"email={data['email']}", status_code=401)
        db.session.commit()
        raise AuthError("Invalid email or password.", code="invalid_credentials")

    audit("auth.login", resource_type="user", resource_id=user.id,
          status_code=200, user_id=user.id)
    db.session.commit()
    return jsonify({
        "data": {
            "access_token": create_access_token(user),
            "refresh_token": create_refresh_token(user),
            "token_type": "Bearer",
        }
    })


@auth_bp.post("/refresh")
@rate_limit("RATELIMIT_AUTH_LIMIT", "RATELIMIT_AUTH_WINDOW")
def refresh():
    payload = decode_token(_get_bearer_token(), expected_type="refresh")
    user = User.query.get(int(payload["sub"]))
    if user is None:
        raise AuthError("User no longer exists.", code="token_invalid")

    audit("auth.refresh", resource_type="user", resource_id=user.id,
          status_code=200, user_id=user.id)
    db.session.commit()
    return jsonify({
        "data": {
            "access_token": create_access_token(user),
            "token_type": "Bearer",
        }
    })


@auth_bp.get("/me")
@auth_required
def me():
    return jsonify({"data": g.current_user.to_dict()})

"""API v1: Note CRUD with pagination, plus admin audit-log access."""
from flask import Blueprint, g, jsonify

from ...audit import audit
from ...auth.jwt_utils import admin_required, auth_required
from ...errors import NotFoundError
from ...extensions import db
from ...models import AuditLog, Note
from ...pagination import paginate
from ...rate_limit import rate_limit
from ...validation import String, validate_json

api_v1 = Blueprint("api_v1", __name__)

NOTE_CREATE_SCHEMA = {
    "title": String(min_length=1, max_length=200),
    "body": String(required=False, default="", max_length=10_000),
}
NOTE_UPDATE_SCHEMA = {
    "title": String(required=False, min_length=1, max_length=200),
    "body": String(required=False, max_length=10_000),
}


def _get_owned_note(note_id: int) -> Note:
    note = Note.query.filter_by(id=note_id, owner_id=g.current_user.id).first()
    if note is None:
        raise NotFoundError("Note not found.")
    return note


@api_v1.get("/notes")
@auth_required
@rate_limit()
def list_notes():
    query = (Note.query.filter_by(owner_id=g.current_user.id)
             .order_by(Note.id.asc()))
    return jsonify(paginate(query))


@api_v1.post("/notes")
@auth_required
@rate_limit()
def create_note():
    data = validate_json(NOTE_CREATE_SCHEMA)
    note = Note(owner_id=g.current_user.id, **data)
    db.session.add(note)
    db.session.flush()
    audit("note.create", resource_type="note", resource_id=note.id, status_code=201)
    db.session.commit()
    return jsonify({"data": note.to_dict()}), 201


@api_v1.get("/notes/<int:note_id>")
@auth_required
@rate_limit()
def get_note(note_id: int):
    return jsonify({"data": _get_owned_note(note_id).to_dict()})


@api_v1.patch("/notes/<int:note_id>")
@auth_required
@rate_limit()
def update_note(note_id: int):
    note = _get_owned_note(note_id)
    data = validate_json(NOTE_UPDATE_SCHEMA)
    for field, value in data.items():
        setattr(note, field, value)
    audit("note.update", resource_type="note", resource_id=note.id,
          status_code=200, detail=f"fields={sorted(data)}")
    db.session.commit()
    return jsonify({"data": note.to_dict()})


@api_v1.delete("/notes/<int:note_id>")
@auth_required
@rate_limit()
def delete_note(note_id: int):
    note = _get_owned_note(note_id)
    db.session.delete(note)
    audit("note.delete", resource_type="note", resource_id=note_id, status_code=204)
    db.session.commit()
    return "", 204


@api_v1.get("/audit-logs")
@admin_required
@rate_limit()
def list_audit_logs():
    query = AuditLog.query.order_by(AuditLog.id.desc())
    return jsonify(paginate(query))
